// AUTHOR CANDIDATE. bigint値はwireではcanonical十進文字列。runtimeはschema/codecが閉集合を検査。
export type Score = Readonly<{ "home": string; "away": string }>
export type Scoreboard = Readonly<{ "inningScores": Score; "hits": string; "errors": string; "strikeouts": string; "walks": string }>
export type StateFields = Readonly<{ "state.half": "top" | "bottom"; "state.count.strikes": string; "state.count.balls": string; "state.outs": string; "state.runners": "empty" | "first" | "second" | "third" | "first-second" | "first-third" | "second-third" | "loaded"; "state.battingOrder": string; "state.tiebreakActive": boolean; "state.gameEnded": boolean; "state.inning": string; "state.score": Score }>
export type StateSnapshot = Readonly<{ "stateFields": StateFields; "scoreboard": Scoreboard }>
export type T1Request = Readonly<{ "eventKind": string; "resultId": string; "pitchEventKind": string; "before": StateSnapshot }>
export type T1Value = Readonly<{ "countEffect": Readonly<{ "strikes": Readonly<{ "kind": "unchanged" }>; "balls": Readonly<{ "kind": "delta"; "value": string }> }>; "plateAppearanceEnded": boolean; "batterDestination": Readonly<{ "kind": "continue" }>; "runnerDefaultAdvance": Readonly<{ "first": Readonly<{ "modality": "not-applicable"; "destination": null }>; "second": Readonly<{ "modality": "not-applicable"; "destination": null }>; "third": Readonly<{ "modality": "not-applicable"; "destination": null }> }>; "outEffect": Readonly<{ "count": string; "targets": readonly [] }>; "statFlags": Readonly<{ "投球回算入アウト": boolean; "投球数": boolean; "奪三振": boolean; "与四球": boolean; "与死球": boolean; "被安打": boolean; "被本塁打": boolean; "失点": boolean; "失策": boolean; "打席": boolean; "打数": boolean; "安打": boolean; "本塁打": boolean; "塁打": boolean; "犠打": boolean; "犠飛": boolean; "四球": boolean; "死球": boolean; "三振": boolean; "打撃妨害出塁": boolean; "走塁妨害出塁": boolean; "得点": boolean; "打点": boolean }>; "after": Readonly<{ "stateFields": Readonly<{ "state.half": "top" | "bottom"; "state.count.strikes": string; "state.count.balls": string; "state.outs": string; "state.runners": "empty" | "first" | "second" | "third" | "first-second" | "first-third" | "second-third" | "loaded"; "state.battingOrder": string; "state.tiebreakActive": boolean; "state.gameEnded": boolean; "state.inning": string; "state.score": Readonly<{ "home": string; "away": string }> }>; "scoreboard": Readonly<{ "inningScores": Readonly<{ "home": string; "away": string }>; "hits": string; "errors": string; "strikeouts": string; "walks": string }> }>; "historyContext": readonly [Readonly<{ "kind": "confirmed-play"; "difference": Readonly<{ "stateFields": Readonly<{ "state.count.balls": Readonly<{ "before": string; "after": string }> }>; "scoreboard": Readonly<{  }>; "statFlags": Readonly<{ "投球回算入アウト": boolean; "投球数": boolean; "奪三振": boolean; "与四球": boolean; "与死球": boolean; "被安打": boolean; "被本塁打": boolean; "失点": boolean; "失策": boolean; "打席": boolean; "打数": boolean; "安打": boolean; "本塁打": boolean; "塁打": boolean; "犠打": boolean; "犠飛": boolean; "四球": boolean; "死球": boolean; "三振": boolean; "打撃妨害出塁": boolean; "走塁妨害出塁": boolean; "得点": boolean; "打点": boolean }> }> }>] }>
export type SavedRuleWire = Readonly<{ "regulationInnings": string; "coldConditions": ReadonlyArray<Readonly<{ "pointDifference": string; "startInning": string }>>; "extensionLimit": (null) | (string); "tiebreak": (null) | (Readonly<{ "startInning": string; "runnerPlacement": string; "leadoffRule": string }>); "dh": boolean }>
export type T2NoEndCore = (Readonly<{ "kind": "evaluated-no-end-condition"; "evaluation_point": "post-play"; "basis": Readonly<{ "regulation": Readonly<{ "kind": "before-regulation-completion"; "regulation_innings": "7"; "observed_inning": "1"; "observed_half": "top" }>; "cold": Readonly<{ "kind": "no-configured-cold-condition" }>; "extra_and_draw": Readonly<{ "kind": "before-extra-inning-boundary"; "configured_extension_limit": null }>; "walk_off": Readonly<{ "kind": "top-half-without-score-change" }> }> }>) | (Readonly<{ "kind": "evaluated-no-end-condition"; "evaluation_point": "post-play"; "basis": Readonly<{ "regulation": Readonly<{ "kind": "before-regulation-completion"; "regulation_innings": "9"; "observed_inning": "1"; "observed_half": "top" }>; "cold": Readonly<{ "kind": "no-configured-cold-condition" }>; "extra_and_draw": Readonly<{ "kind": "before-extra-inning-boundary"; "configured_extension_limit": null }>; "walk_off": Readonly<{ "kind": "top-half-without-score-change" }> }> }>) | (Readonly<{ "kind": "evaluated-no-end-condition"; "evaluation_point": "post-play"; "basis": Readonly<{ "regulation": Readonly<{ "kind": "before-regulation-completion"; "regulation_innings": "9"; "observed_inning": "1"; "observed_half": "top" }>; "cold": Readonly<{ "kind": "no-configured-cold-condition" }>; "extra_and_draw": Readonly<{ "kind": "before-extra-inning-boundary"; "configured_extension_limit": "9" }>; "walk_off": Readonly<{ "kind": "top-half-without-score-change" }> }> }>)
export type T2NotEvaluatedCore = Readonly<{ "kind": "not-evaluated"; "reason": "input-not-in-closed-unit" | "evaluation-unavailable" }>
export type CombinedRequest = Readonly<{ "t1": T1Request; "rules": SavedRuleWire }>
export type CombinedSuccess = Readonly<{ "ok": true; "value": Readonly<{ "t1": T1Value; "t2": T2NoEndCore }> }>
export type ExistingT1Failure = Readonly<{ "ok": false; "error": Readonly<{ "code": "INVALID_JSON" | "INVALID_REQUEST" | "INVALID_DECIMAL_INTEGER" | "UNSUPPORTED_T1_SCOPE" }> }>
export type T2NotEvaluatedResponse = Readonly<{ "ok": false; "error": Readonly<{ "code": "T2_NOT_EVALUATED" }>; "value": Readonly<{ "t1": T1Value; "t2": T2NotEvaluatedCore }> }>
export type CombinedResponse = (CombinedSuccess) | (ExistingT1Failure) | (T2NotEvaluatedResponse)
